import{c as a,Q as e,j as d,m as s}from"./chunks/framework.CWBTDBPu.js";const k=JSON.parse('{"title":"YuRandomTeleport 安装部署","description":"","frontmatter":{"title":"YuRandomTeleport 安装部署"},"headers":[],"relativePath":"plugins/items/yu-random-teleport/install.md","filePath":"plugins/items/yu-random-teleport/install.md"}'),i={name:"plugins/items/yu-random-teleport/install.md"};function l(o,t,n,r,h,c){return e(),d("div",null,[...t[0]||(t[0]=[s(`<h1 id="yurandomteleport-安装部署" tabindex="-1">YuRandomTeleport 安装部署 <a class="header-anchor" href="#yurandomteleport-安装部署" aria-label="Permalink to &quot;YuRandomTeleport 安装部署&quot;">​</a></h1><h2 id="环境要求" tabindex="-1">环境要求 <a class="header-anchor" href="#环境要求" aria-label="Permalink to &quot;环境要求&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>要求</th></tr></thead><tbody><tr><td>Java</td><td>Java 8 及以上。源码以 <code>sourceCompatibility = JavaVersion.VERSION_1_8</code> 构建。</td></tr><tr><td>服务端</td><td>Spigot、Paper、Paper 衍生端，以及 Mohist、Arclight、Youer 等兼容 Bukkit API 的混合端。</td></tr><tr><td>Minecraft</td><td>目标适配 <code>1.8.x-1.26.x</code>。源码使用 Spigot API <code>1.8-R0.1-SNAPSHOT</code> 编译，并通过反射读取新版世界高度。建议在正式服同版本测试后上线。</td></tr><tr><td>经济扣费</td><td>可选。需要 Vault 与一个 Vault 经济服务提供者，例如 EssentialsX Economy、CMI 或其他经济插件。</td></tr><tr><td>网络访问</td><td>bStats 统计会尝试访问统计服务；不影响核心随机传送功能。</td></tr></tbody></table><h2 id="兼容卖点" tabindex="-1">兼容卖点 <a class="header-anchor" href="#兼容卖点" aria-label="Permalink to &quot;兼容卖点&quot;">​</a></h2><p>YuRandomTeleport 的核心定位不是只服务某一个新版本，而是尽量覆盖从老版本生存服到新版本混合端的随机传送需求。</p><table tabindex="0"><thead><tr><th>兼容范围</th><th>说明</th></tr></thead><tbody><tr><td>Minecraft 版本</td><td>目标适配 <code>1.8.x-1.26.x</code>。</td></tr><tr><td>Bukkit 系服务端</td><td>Spigot、Paper、Paper 衍生端。</td></tr><tr><td>混合端</td><td>Mohist、Arclight、Youer 等 Bukkit API 混合端。</td></tr><tr><td>世界高度</td><td>旧版本使用传统高度逻辑；新版通过反射读取 <code>getMinHeight</code> / <code>getMaxHeight</code>，适配负高度和更高世界上限。</td></tr><tr><td>下界传送</td><td>下界不依赖最高地表点，而是在配置高度范围内扫描候选 Y，降低混合端和不同世界生成器下卡墙概率。</td></tr></tbody></table><h2 id="从源码构建" tabindex="-1">从源码构建 <a class="header-anchor" href="#从源码构建" aria-label="Permalink to &quot;从源码构建&quot;">​</a></h2><p>压缩包内是 Gradle 项目，已包含 <code>gradlew</code> 与 <code>gradlew.bat</code>。在插件源码目录执行：</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.\\</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">gradlew.bat</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> clean</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> shadowJar</span></span></code></pre></div><p>构建完成后通常会在 <code>build/libs/</code> 下生成包含依赖重定位后的 jar。发布部署时优先使用 <code>shadowJar</code> 产物，因为 bStats 已被重定位到插件包内。</p><h2 id="部署到服务端" tabindex="-1">部署到服务端 <a class="header-anchor" href="#部署到服务端" aria-label="Permalink to &quot;部署到服务端&quot;">​</a></h2><ol><li>停止服务端。</li><li>将构建出的 <code>YuRandomTeleport-1.1.2.2-all.jar</code> 放入服务端 <code>plugins/</code> 目录。</li><li>启动服务端，等待插件生成 <code>plugins/YuRandomTeleport/config.yml</code> 与 <code>messages.yml</code>。</li><li>在控制台确认出现 <code>YuRandomTeleport 已启用</code>。</li><li>进入游戏执行 <code>/rtp help</code> 或 <code>/yurtp help</code> 检查命令是否注册成功。</li></ol><h2 id="首次配置检查" tabindex="-1">首次配置检查 <a class="header-anchor" href="#首次配置检查" aria-label="Permalink to &quot;首次配置检查&quot;">​</a></h2><p>首次上线前至少检查这些配置：</p><table tabindex="0"><thead><tr><th>配置</th><th>默认值</th><th>建议</th></tr></thead><tbody><tr><td><code>world-blacklist</code></td><td><code>lobby</code></td><td>将主城、登录服、小游戏大厅等世界加入黑名单。</td></tr><tr><td><code>world-whitelist</code></td><td>空列表</td><td>如果只允许资源世界 RTP，建议改用白名单。白名单非空时会覆盖黑名单。</td></tr><tr><td><code>default.radius.min</code></td><td><code>500</code></td><td>控制玩家离出生点或世界坐标中心的最小距离。</td></tr><tr><td><code>default.radius.max</code></td><td><code>2000</code></td><td>控制随机范围。大型资源世界可调高。</td></tr><tr><td><code>teleport.wait-seconds</code></td><td><code>5</code></td><td>PVP 或生存服建议保留等待时间，防止战斗逃脱。</td></tr><tr><td><code>teleport.cancel-on-move</code></td><td><code>true</code></td><td>正式服建议保持开启。</td></tr><tr><td><code>cooldown.seconds</code></td><td><code>3</code></td><td>生产环境通常建议根据玩法提高到 30 秒、60 秒或更高。</td></tr><tr><td><code>default.safety.max-attempts</code></td><td><code>32</code></td><td>找不到安全点时可适当增加，但过高会增加瞬时区块加载压力。</td></tr></tbody></table><h2 id="接入-vault-经济" tabindex="-1">接入 Vault 经济 <a class="header-anchor" href="#接入-vault-经济" aria-label="Permalink to &quot;接入 Vault 经济&quot;">​</a></h2><p>经济功能默认关闭：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">economy</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  enabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span></span></code></pre></div><p>启用扣费需要同时满足：</p><ol><li>安装 Vault。</li><li>安装并启用一个 Vault 经济服务提供者。</li><li>将 <code>economy.enabled</code> 改为 <code>true</code>。</li><li>在 <code>default.cost</code> 或 <code>worlds.&lt;世界名&gt;.cost</code> 设置费用。</li></ol><p>示例：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">economy</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  enabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">default</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  cost</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">100.0</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">worlds</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  resource</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    cost</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">50.0</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  world_nether</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    cost</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">250.0</span></span></code></pre></div><p>如果开启经济但没有 Vault，控制台会提示安装 Vault。如果检测到 Vault 但没有经济服务提供者，控制台会提示安装经济插件。</p><h2 id="升级已有版本" tabindex="-1">升级已有版本 <a class="header-anchor" href="#升级已有版本" aria-label="Permalink to &quot;升级已有版本&quot;">​</a></h2><p>插件会读取 <code>config-version</code> 和 <code>messages-version</code>，当版本落后时合并默认配置并备份旧文件。</p><table tabindex="0"><thead><tr><th>文件</th><th>当前版本</th><th>备份行为</th></tr></thead><tbody><tr><td><code>config.yml</code></td><td><code>5</code></td><td>更新时生成类似 <code>config.yml.bak4</code> 的备份。</td></tr><tr><td><code>messages.yml</code></td><td><code>4</code></td><td>更新时生成类似 <code>messages.yml.bak3</code> 的备份。</td></tr></tbody></table><p>升级建议：</p><ol><li>停服备份 <code>plugins/YuRandomTeleport/</code>。</li><li>替换 jar。</li><li>启动一次服务端，让插件自动合并新配置。</li><li>对比备份文件与新文件，确认自定义项仍然保留。</li><li>执行一次 <code>/rtp</code>、一次 <code>/yurtp reload</code> 和一次管理员代传送测试。</li></ol><h2 id="卸载" tabindex="-1">卸载 <a class="header-anchor" href="#卸载" aria-label="Permalink to &quot;卸载&quot;">​</a></h2><ol><li>停止服务端。</li><li>删除 <code>plugins/</code> 中的 YuRandomTeleport jar。</li><li>如不再需要配置，删除 <code>plugins/YuRandomTeleport/</code> 目录。</li></ol><p>插件不会创建数据库表；经济扣费由 Vault 经济插件处理。</p>`,31)])])}const u=a(i,[["render",l]]);export{k as __pageData,u as default};
